#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

PROTO="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$PROTO"
ENV_FILE="$PROTO/logs/observations.env"
mkdir -p "$PROTO/logs"

ARM="${1:-}"
case "$ARM" in
  accessibility-only|request-only|tap-only|request-and-tap) ;;
  *)
    printf 'usage: %s {accessibility-only|request-only|tap-only|request-and-tap}\n' "$0" >&2
    exit 2
    ;;
esac

BUNDLE_ID="dev.openstream.prototype.tccim89.$ARM"
export BUNDLE_ID
PREFIX="$(printf '%s' "$ARM" | sed 's/-/_/g' | tr '[:lower:]' '[:upper:]')"
AX_PANE="x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"
IM_PANE="x-apple.systempreferences:com.apple.preference.security?Privacy_ListenEvent"

write_observation() {
  write_env "${PREFIX}_$1" "$2"
}

trigger_button() {
  case "$ARM" in
    accessibility-only) say "Click 'Accessibility request only'." ;;
    request-only) say "Click 'IOHIDRequestAccess only'." ;;
    tap-only) say "Click 'Listen-only event tap only'." ;;
    request-and-tap) say "Click 'Request then event tap'." ;;
  esac
}

banner "Input Monitoring probe (issue #89)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Choose a clean experiment arm"
say "This run measures: $ARM"
say "Its fresh bundle identifier is: $BUNDLE_ID"
warn "The app will create real TCC entries. The final stage removes this arm's entries."
pause "Press Enter when ready."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Reset and build the arm"
say "Resetting only this prototype bundle prevents an old grant from contaminating the arm."
if ! confirm "Reset this arm's Input Monitoring and Accessibility entries, then build?"; then
  exit 1
fi
/usr/bin/tccutil reset ListenEvent "$BUNDLE_ID" >/dev/null 2>&1 || true
/usr/bin/tccutil reset Accessibility "$BUNDLE_ID" >/dev/null 2>&1 || true
./build.sh
pause "Build complete. Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Capture the denied baseline"
./readstate.sh "$ARM-baseline" check
say "The hotkey helper should be denied, and both responsible executables should name TCCProbe."
ask BASELINE_STATE "Record the printed hotkey state in one line:"
write_observation BASELINE_STATE "$BASELINE_STATE"
open_url "$IM_PANE"
step "Before pressing the trigger, record every entry name visible under Input Monitoring."
ask BASELINE_ENTRY_NAMES "Exact Input Monitoring entry names before trigger (or 'none'):"
write_observation BASELINE_ENTRY_NAMES "$BASELINE_ENTRY_NAMES"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Run exactly one trigger"
open "$APP" >/dev/null 2>&1 || true
trigger_button
step "Do not switch a row on yet. If macOS opens System Settings, leave the pane ready for the next stage."
pause "Trigger clicked. Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Record what the pane shows now"
BUNDLE_ID="$BUNDLE_ID" ./readstate.sh "$ARM-after-trigger" check
open_url "$IM_PANE"
step "Refresh or revisit Input Monitoring if necessary, then record every visible entry name."
step "Record whether the row appeared immediately, after opening the pane, or only after revisiting it."
ask AFTER_ENTRY_NAMES "Exact entry names after trigger and when they appeared:"
write_observation AFTER_ENTRY_NAMES "$AFTER_ENTRY_NAMES"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Optionally grant the observed row"
if confirm "Is there a row for this arm that you can switch on?"; then
  open_url "$IM_PANE"
  step "Switch on only the row created by this arm. If macOS asks you to quit and reopen TCCProbe, do so."
  pause "Input Monitoring switched on (or System Settings requested a relaunch)."
  GRANT_ACTION="switched-on"
else
  say "Leave the pane unchanged; an absent row is an important result."
  GRANT_ACTION="no-row-or-not-switched-on"
fi
write_observation GRANT_ACTION "$GRANT_ACTION"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Capture effective state"
BUNDLE_ID="$BUNDLE_ID" ./readstate.sh "$ARM-final" check
ask FINAL_STATE "Record the final hotkey state, including reported and functional values:"
write_observation FINAL_STATE "$FINAL_STATE"
ask PANE_TIMING "When did the row appear, and did it remain visible after the grant?"
write_observation PANE_TIMING "$PANE_TIMING"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Clean up the real TCC entries"
warn "This removes only $BUNDLE_ID from the two permission services and deletes the local probe app."
step "Quit the visible TCCProbe window with Cmd-Q before continuing."
pause "TCCProbe is quit."
if ! confirm "Run cleanup now?"; then
  warn "Cleanup skipped. Remove the row manually and run tccutil reset before deleting the prototype."
  exit 1
fi
/usr/bin/tccutil reset ListenEvent "$BUNDLE_ID" >/dev/null 2>&1 || true
/usr/bin/tccutil reset Accessibility "$BUNDLE_ID" >/dev/null 2>&1 || true
rm -rf "$APP"
say "Saved API captures under $PROTO/logs/ and observations in $ENV_FILE."

finish
